use std::sync::{Arc, Mutex};

/// Copysign returns a value with the magnitude of f
/// and the sign of sign.
pub fn copysign(f: Arc<Mutex<Option<f64>>>, sign: Arc<Mutex<Option<f64>>>) -> f64 {
    const signBit: u64 = 1 << 63;

    float64frombits(Arc::new(Mutex::new(Some({ let __tmp_x = { let __tmp_x = float64bits(Arc::new(Mutex::new(Some({ let __arg_holder = f.clone(); let __arg_guard = __arg_holder.lock().unwrap(); (*__arg_guard.as_ref().unwrap()).clone() })))); let __tmp_y = signBit as u64; __tmp_x & ! __tmp_y }; let __tmp_y = { let __tmp_x = float64bits(Arc::new(Mutex::new(Some({ let __arg_holder = sign.clone(); let __arg_guard = __arg_holder.lock().unwrap(); (*__arg_guard.as_ref().unwrap()).clone() })))); let __tmp_y = signBit as u64; __tmp_x & __tmp_y }; __tmp_x | __tmp_y }))))
}